'use strict';
const {randomUUID}=require('node:crypto');
// One cancellable renderer worker performs full decoding off the main thread.
class AssemblyPhotoDecoder{
 constructor({getWindow,url,timeout=10000}){this.getWindow=getWindow;this.url=url;this.timeout=timeout;this.job=null;}
 owns(e){const w=this.getWindow();return !!(w&&!w.isDestroyed()&&e.sender===w.webContents&&e.senderFrame===w.webContents.mainFrame&&e.senderFrame.url===this.url);}
 decode(picture,{thumbnail=false,signal}={}){if(signal?.aborted)return Promise.reject(Error('Photograph checking was cancelled.'));if(this.job)return Promise.reject(Error('A photograph is already being checked. Please wait.'));const expected=require('./assembly-photo.cjs').admission(picture);return new Promise((resolve,reject)=>{const job={id:randomUUID(),resolve,reject,expected,thumbnail,signal};this.job=job;job.abort=()=>{try{const w=this.getWindow();if(w&&!w.isDestroyed())w.webContents.send('sf:assembly-photo-cancel',job.id);}catch{}finally{this.finish(Error('Photograph checking was cancelled.'));}};signal?.addEventListener('abort',job.abort,{once:true});job.timer=setTimeout(()=>{try{const w=this.getWindow();if(w&&!w.isDestroyed())w.webContents.send('sf:assembly-photo-cancel',job.id);}catch{/* Window closed during timeout. */}finally{this.finish(Error('Photograph decoding timed out. Choose another image.'));}},this.timeout);job.timer.unref?.();try{this.getWindow().webContents.send('sf:assembly-photo-decode',{id:job.id,picture,thumbnail});}catch(e){this.finish(e);}});}
 receive(e,id,result){if(!this.owns(e)||this.job?.id!==id)return;const expected=this.job.expected,valid=result?.ok===true&&Number.isSafeInteger(result.width)&&Number.isSafeInteger(result.height)&&result.width*result.height===expected.width*expected.height&&(result.width===expected.width||result.width===expected.height);let thumb=result?.thumbnail;if(this.job.thumbnail){try{if(!thumb||!['image/png','image/jpeg'].includes(thumb.mime)||!(thumb.bytes instanceof Uint8Array)||thumb.bytes.length>2*1024*1024)throw Error();const d=require('./assembly-photo.cjs').admission('data:'+thumb.mime+';base64,'+Buffer.from(thumb.bytes).toString('base64'));const scale=Math.min(1,512/result.width,512/result.height);if(d.width!==Math.max(1,Math.round(result.width*scale))||d.height!==Math.max(1,Math.round(result.height*scale))||d.width!==thumb.width||d.height!==thumb.height)throw Error();}catch{thumb=null;}}this.finish(valid&&(!this.job.thumbnail||thumb)?null:Error('This photograph could not be opened. Choose another PNG, JPEG or WebP image.'),this.job.thumbnail?thumb:undefined);}
 finish(error,value){const job=this.job;if(!job)return;this.job=null;clearTimeout(job.timer);job.signal?.removeEventListener('abort',job.abort);if(error)job.reject(error);else job.resolve(value);}
 reset(){this.finish(Error('Photograph decoding was interrupted. Try again.'));}
}
module.exports={AssemblyPhotoDecoder};
